import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, rmSync } from 'node:fs';
import { join } from 'node:path';
import test from 'node:test';

const projectDir = join(import.meta.dirname, '..');

function runBadge(file: string, operation: string, ...args: string[]) {
  const result = spawnSync(process.execPath, ['src/badge.ts', file, operation, ...args], {
    cwd: projectDir,
    encoding: 'utf8',
    timeout: 5000,
  });

  assert.ifError(result.error);
  assert.equal(result.status, 0, `badge ${operation} failed: ${result.stderr}`);
  return result.stdout;
}

test('shows the saved label on the next launch', (t) => {
  const directory = mkdtempSync(join(projectDir, '.badge-test-'));
  t.after(() => rmSync(directory, { recursive: true, force: true }));

  const file = join(directory, 'shift-badge');
  const label = 'Evening shift';

  runBadge(file, 'set', label);

  assert.equal(runBadge(file, 'show'), `${label}\n`);
  assert.equal(runBadge(join(directory, 'missing-badge'), 'show'), 'Default\n');
});
